/// <summary>
/// extension of class MCRFullTextSearch
/// </summary>
[ExtensionOf(classStr(MCRFullTextSearch))]
final class AVAMCRFullTextSearch_Extension
{
}

Method.Source:
/// <summary>
/// AVA <c>buildSearchTextFromSet</c>
/// </summary>
/// <param name = "_table">Common</param>
/// <param name = "_fieldSet">Set</param>
/// <returns>MCRSearchText</returns>
public static MCRSearchText buildSearchTextFromSet(Common _table, Set _fieldSet)
{
    MCRSearchText   MCRSearchText;
    InventItemBarcode   inventItemBarcode;

    MCRSearchText = next buildSearchTextFromSet(_table,_fieldSet);
    //DictTable dictTable = new DictTable(_table.TableId);

    if(_fieldSet.in('ItemBarCode') && _table.TableId == tableNum(MCRProductSearchView))
    {
        MCRProductSearchView        productSearchView = _table;
        ItemId      locItemId = productSearchView.ItemId;
        Str1260     barCodeStr; 
        if (locItemId)
        {
            while select  inventItemBarcode 
                where inventItemBarcode.itemId == locItemId
            {
                if(barCodeStr != '')
                {
                    barCodeStr += ' ';
                }
                barCodeStr += inventItemBarcode.itemBarCode;
            }
        }

        if (barCodeStr != '')
        {
            MCRSearchText += ' ' + barCodeStr;
        }

    }

    return MCRSearchText;
}
